// SwiftUI resolves concatenation recursively. Pair adjacent values so large
// paragraphs retain every run in order with logarithmic composition depth.
func balancedTextReduction<Value>(
  _ values: [Value], combine: (Value, Value) -> Value
) -> Value? {
  var level = values
  while level.count > 1 {
    var next: [Value] = []
    next.reserveCapacity((level.count + 1) / 2)
    for index in stride(from: 0, to: level.count, by: 2) {
      if index + 1 < level.count {
        next.append(combine(level[index], level[index + 1]))
      } else {
        next.append(level[index])
      }
    }
    level = next
  }
  return level.first
}

