// Core Animation rejects an enormous single Text backing layer at larger
// Dynamic Type sizes. Bound each drawing fragment, not the logical paragraph:
// keep every attribute/character and apply paragraph block spacing only once.
// A continuation can wrap early at a chunk boundary. This bounded reflow is
// intentional: exact giant-Text line placement is less important than readable,
// complete content at accessible sizes. It adds no semantic paragraph or gap.
func paragraphRenderingChunks(_ content: AttributedString) -> [AttributedString] {
  let maximumCharacters = 2048
  guard content.characters.count > maximumCharacters else { return [content] }
  var chunks: [AttributedString] = []
  var start = content.startIndex
  while start < content.endIndex {
    let limit = content.characters.index(
      start, offsetBy: maximumCharacters, limitedBy: content.endIndex
    ) ?? content.endIndex
    let end: AttributedString.Index
    if limit < content.endIndex,
      let space = content.characters[start..<limit].lastIndex(where: { $0.isWhitespace })
    {
      end = content.characters.index(after: space)
    } else {
      end = limit
    }
    chunks.append(AttributedString(content[start..<end]))
    start = end
  }
  return chunks
}
